<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class FxQuote extends Model { use HasUuids; public $incrementing=false; protected $keyType='string'; protected $fillable=['quote_reference','user_id','source_wallet_currency_account_id','target_wallet_currency_account_id','pair_id','rate_snapshot_id','source_currency_code','target_currency_code','source_amount_minor','mid_market_rate','exchange_rate','rate_direction','provider_spread_bps','platform_markup_bps','platform_fee_minor','provider_reference','estimated_target_amount_minor','rounding_policy','status','sandbox_only','expires_at','metadata']; protected $casts=['sandbox_only'=>'boolean','expires_at'=>'datetime','metadata'=>'array']; public function isExpired(): bool { return now()->greaterThanOrEqualTo($this->expires_at); } public function sourceAccount(): BelongsTo { return $this->belongsTo(WalletCurrencyAccount::class,'source_wallet_currency_account_id'); } public function targetAccount(): BelongsTo { return $this->belongsTo(WalletCurrencyAccount::class,'target_wallet_currency_account_id'); } public function pair(): BelongsTo { return $this->belongsTo(FxPair::class); } public function user(): BelongsTo { return $this->belongsTo(User::class); } }
